package main

import (
	"errors"
	"fmt"
	"time"

	"github.com/descikazuyq/warranty-parts/warranty"
)

func main() {
	s := warranty.NewStore()
	must := func(err error) {
		if err != nil {
			panic(err) // 正常分支遇到意外错误立即停止
		}
	}

	purchase := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	now := purchase.AddDate(0, 0, 10) // 2026-01-11，保修期内
	expiry := purchase.AddDate(0, 0, 40)

	// 空除外清单：不按故障代码除外
	must(s.RegisterProduct("P0", purchase, 30, nil))
	fmt.Println("P0 registered with empty excluded list")

	// 清单内空字符串
	err := s.RegisterProduct("PX", purchase, 30, []string{""})
	fmt.Println("PX empty-string code:", errors.Is(err, warranty.ErrInvalidParam))
	_, err = s.Product("PX")
	fmt.Println("PX not saved:", errors.Is(err, warranty.ErrNotFound))

	// 正式产品 + 备件
	must(s.RegisterProduct("P1", purchase, 30, []string{"BROKEN_SEAL"}))
	must(s.RegisterPart("PART-A", 10))

	// 空故障代码请求
	err = s.SubmitRequest("REQ-BAD", "P1", "")
	fmt.Println("empty fault code:", errors.Is(err, warranty.ErrInvalidParam))
	_, err = s.Request("REQ-BAD")
	fmt.Println("REQ-BAD not saved:", errors.Is(err, warranty.ErrNotFound))

	codes := []string{"BROKEN_SEAL", "broken_seal", " BROKEN_SEAL "}
	reqs := []string{"REQ-1", "REQ-2", "REQ-3"}
	for i, code := range codes {
		must(s.SubmitRequest(reqs[i], "P1", code))
		r, err := s.Request(reqs[i])
		must(err)
		fmt.Printf("%s saved, code=%q\n", reqs[i], r.FaultCode)
	}

	for _, rid := range reqs {
		rv, err := s.RequestView(rid, now)
		must(err)
		fmt.Printf("%s eligible=%v excluded=%v reasons=%v\n",
			rid, rv.Eligibility.Eligible, rv.Eligibility.Excluded, rv.Eligibility.Reasons)
	}

	commits := []string{"COMMIT-1", "COMMIT-2", "COMMIT-3"}
	for i, rid := range reqs {
		_, err := s.Reserve(commits[i], rid, "PART-A", 1, expiry, now)
		if i == 0 {
			fmt.Printf("%s -> ErrIneligible: %v\n", commits[i], errors.Is(err, warranty.ErrIneligible))
		} else {
			must(err)
			fmt.Printf("%s reserved ok\n", commits[i])
		}
	}

	_, err = s.Commitment("COMMIT-1")
	fmt.Println("COMMIT-1 absent:", errors.Is(err, warranty.ErrNotFound))

	ps, err := s.PartStatus("PART-A", now)
	must(err)
	fmt.Println(ps.PhysicalRemaining, ps.ActiveOccupied, ps.Committable)
}

